/// The bytes an RFC 8446 §4.4.3 `CertificateVerify` signature covers.
///
/// 64 spaces, the context string, a zero byte, then a 32-byte hash. The hash is a
/// fixed value rather than a transcript of anything: what the vectors below pin is
/// the verification arithmetic and the dispatch to the right key type, and a real
/// transcript is already pinned by the RFC 8448 flight. The *shape* is what a test
/// asserts here, so a generator change that dropped the context string is visible.
const CV_SIGNED_DATA_HEX: &str = "20202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020202020544c5320312e332c2073657276657220436572746966696361746556657269667900c1d976346ac3a5ca3da52981c19ab6afe878ee0c96ffaba36c3462c2d0651dda";

/// A `CertificateVerify` signature, verified by the OpenSSL CLI before it was
/// written down here. RSA-PSS and ECDSA both draw fresh randomness, so these bytes
/// differ on every regeneration — the tests assert that they verify, not that they
/// match anything.
const CV_RSA_SIGNATURE_HEX: &str = "";
const CV_ECDSA_SIGNATURE_HEX: &str = "3045022100dd434d7c8d8c3f06d4977be1245726c7694227ec4cbe754bfce03f3ed584c0b70220774ae5cb04668ed15ccdcb833526887c89f633f90cc02637258e811da1b8ae11";

/// The same PSS signature with its last byte flipped: the bytes are a valid
/// length and the scheme is one we offered, so only the arithmetic can refuse it.
const CV_RSA_SIGNATURE_FORGED_HEX: &str = "";

/// Signatures over [`CV_SIGNED_DATA_HEX`], and which of them must verify.
///
/// `leaf` names the fixture whose private key made the signature, so the test
/// looks up the public key it has to be checked against rather than restating it.
const CV_VECTORS: &[CvVector] = &[
    CvVector {
        name: "rsa-pss-leaf-signed",
        leaf: "LEAF_RSA",
        scheme: 0x0804,
        signature_hex: CV_RSA_SIGNATURE_HEX,
        okay: true,
    },
    CvVector {
        name: "rsa-pss-leaf-forged",
        leaf: "LEAF_RSA",
        scheme: 0x0804,
        signature_hex: CV_RSA_SIGNATURE_FORGED_HEX,
        okay: false,
    },
    CvVector {
        name: "ecdsa-leaf-signed",
        leaf: "LEAF_EC_VALID",
        scheme: 0x0403,
        signature_hex: CV_ECDSA_SIGNATURE_HEX,
        okay: true,
    },
];

